#include <cstdint>
#include <vector>

enum class Connect { Connected, Busy, NoServer };

class PipeServer
{
public:
    explicit PipeServer(int maxInstances) {}
    bool createInstance() { return false; }
    Connect clientConnects(std::uint32_t pid, int& instance) { return Connect::NoServer; }
    void clientDisconnects(int instance) {}
    void closeInstance(int instance) {}
    int listening() const { return 0; }
    std::vector<std::uint32_t> clients() const { return {}; }
};

solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>
#include <vector>

enum class Connect { Connected, Busy, NoServer };

class PipeServer
{
public:
    explicit PipeServer(int maxInstances) : limit{ maxInstances } {}

    bool createInstance()
    {
        if (static_cast<int>(instances.size()) >= limit) return false;
        instances[nextNumber++] = std::nullopt;
        return true;
    }

    Connect clientConnects(std::uint32_t pid, int& instance)
    {
        if (instances.empty()) return Connect::NoServer;
        for (auto& [number, client] : instances)
        {
            if (client) continue;
            client = pid;
            instance = number;
            return Connect::Connected;
        }
        return Connect::Busy;
    }

    void clientDisconnects(int instance)
    {
        const auto it{ instances.find(instance) };
        if (it != instances.end()) it->second.reset();
    }

    void closeInstance(int instance) { instances.erase(instance); }

    int listening() const
    {
        int n{ 0 };
        for (const auto& entry : instances) if (!entry.second) ++n;
        return n;
    }

    std::vector<std::uint32_t> clients() const
    {
        std::vector<std::uint32_t> out;
        for (const auto& entry : instances) if (entry.second) out.push_back(*entry.second);
        return out;
    }

private:
    int limit;
    int nextNumber{ 0 };
    std::map<int, std::optional<std::uint32_t>> instances;
};

unitTests:
TEST("no server, then a connection") {
    PipeServer s{ 4 };
    int instance{ -1 };
    CHECK(s.clientConnects(100, instance) == Connect::NoServer);
    CHECK(s.createInstance());
    CHECK_EQ(s.listening(), 1);
    CHECK(s.clientConnects(100, instance) == Connect::Connected);
    CHECK_EQ(instance, 0);
    CHECK_EQ(s.listening(), 0);
    CHECK(s.clientConnects(200, instance) == Connect::Busy);
}
TEST("the accept loop keeps one instance listening") {
    PipeServer s{ 3 };
    int a{}, b{}, c{};
    s.createInstance();
    s.clientConnects(10, a);
    s.createInstance();
    s.clientConnects(20, b);
    s.createInstance();
    s.clientConnects(30, c);
    CHECK_EQ(c, 2);
    CHECK(!s.createInstance());
    CHECK_EQ(s.clients(), (std::vector<std::uint32_t>{ 10, 20, 30 }));
    int d{};
    CHECK(s.clientConnects(40, d) == Connect::Busy);
    s.clientDisconnects(b);
    CHECK(s.clientConnects(40, d) == Connect::Connected);
    CHECK_EQ(d, 1);
    CHECK_EQ(s.clients(), (std::vector<std::uint32_t>{ 10, 40, 30 }));
}
TEST("closing instances") {
    PipeServer s{ 2 };
    int a{};
    s.createInstance();
    s.createInstance();
    s.clientConnects(5, a);
    s.closeInstance(a);
    CHECK(s.clients().empty());
    CHECK_EQ(s.listening(), 1);
    CHECK(s.createInstance());
    int b{};
    s.clientConnects(6, b);
    CHECK_EQ(b, 1);
    s.closeInstance(1);
    s.closeInstance(2);
    CHECK(s.clientConnects(7, b) == Connect::NoServer);
}

